def apply_operation(n):
    if n < 0:
        raise ValueError("Input must be a positive integer.")
    if n == 0:
        return 0 # Or handle based on how 0 should behave. Assuming positive start.

    d = n % 10
    q = n // 10
    return q + 3 * d

def generate_sequence(start_n, limit=15):
    sequence = [start_n]
    current_n = start_n
    for _ in range(limit):
        next_n = apply_operation(current_n)
        sequence.append(next_n)
        current_n = next_n
    return sequence

start_values = [12, 23, 99, 101, 125]
results = {}

for n in start_values:
    results[n] = generate_sequence(n)

for n, seq in results.items():
    print(f"Starting value n={n}:")
    print(seq)

def operation(n):
    """Performs the defined operation on n."""
    if n == 0:
        # Although the input is positive integer n, we might hit 0 during the process.
        # Based on the examples (n=2 -> 6), the result seems to remain positive
        # unless n is 0 initially, which is excluded. We handle n>=1.
        return 0

    d = n % 10
    n_prime = n // 10
    n_new = n_prime + 3 * d
    return n_new

def analyze_sequence(start_n, max_iterations=100):
    """Analyzes the sequence starting from start_n until a cycle is detected."""
    sequence = [start_n]
    history = {start_n: 0}  # Value: Iteration index
    current_n = start_n

    for i in range(1, max_iterations + 1):
        next_n = operation(current_n)

        if next_n in history:
            # Cycle detected
            start_of_cycle_index = history[next_n]
            cycle_elements = sequence[start_of_cycle_index:]
            cycle_length = len(cycle_elements)

            return {
                "start_n": start_n,
                "cycle_found": True,
                "entry_point": next_n,
                "start_index": start_of_cycle_index,
                "cycle_length": cycle_length,
                "cycle_elements": cycle_elements
            }

        sequence.append(next_n)
        history[next_n] = i
        current_n = next_n

    # If no cycle is found within max_iterations
    return {
        "start_n": start_n,
        "cycle_found": False,
        "max_iterations_reached": True,
        "sequence": sequence
    }

# Test all integers from 1 to 29
results = {}
for n in range(1, 30):
    results[n] = analyze_sequence(n)

# Process and format results
summary = {}
for n, result in results.items():
    if result["cycle_found"]:
        cycle_info = {
            "start_n": n,
            "length": result["cycle_length"],
            "elements": result["cycle_elements"]
        }
        summary[n] = cycle_info
    else:
        # Should not happen if the behavior is purely cyclic or converging rapidly
        pass 

# Print the required summary
print("--- Analysis Summary ---")
print("Fixed Points (Cycle Length 1):")
fixed_points = {}
for n, info in summary.items():
    if info['length'] == 1:
        fixed_points[n] = info['elements'][0]

if fixed_points:
    print(fixed_points)
else:
    print("None found.")

print("\nOther Attracting Cycles (Length > 1):")
cycles = {}
for n, info in summary.items():
    if info['length'] > 1:
        cycles[n] = info

if cycles:
    for n, info in cycles.items():
        print(f"Start N={n}: Length={info['length']}, Cycle={info['elements']}")
else:
    print("None found.")
